mapper.select:
SELECT * FROM material_inventory

    is_deleted = 0

        AND material_name LIKE CONCAT('%', #{dto.materialName}, '%')


        AND material_type = #{dto.materialType}


        AND specification LIKE CONCAT('%', #{dto.specification}, '%')


        AND batch_no LIKE CONCAT('%', #{dto.batchNo}, '%')


        AND inventory_status = #{dto.inventoryStatus}


        AND quantity >= #{dto.minQuantity}


        AND quantity <= #{dto.maxQuantity}


        AND unit_price >= #{dto.minUnitPrice}


        AND unit_price <= #{dto.maxUnitPrice}


        AND supplier LIKE CONCAT('%', #{dto.supplier}, '%')


        AND warehouse_location LIKE CONCAT('%', #{dto.warehouseLocation}, '%')


        AND create_time >= #{dto.createStartTime}


        AND create_time <= #{dto.createEndTime}


ORDER BY ${dto.orderBy} ${dto.orderType}
